macro.command:
// 物品 On Use：postActiveEffects 选择并执行。
const greater = true;
const pass = args[0]?.macroPass;
if (pass !== "postActiveEffects" || workflow.aborted) return;
if (args[0]?.tag === "TargetOnUse" || workflow.item.uuid !== macroItem.uuid) return;
const key = greater ? "classpackGreaterRestoration" : "classpackLesserRestoration";
const title = greater ? "高等复原术" : "次级复原术";
const dialogs = dnd5eClasspack.dialogUtils;
const names = { blinded: "目盲", deafened: "耳聋", paralyzed: "麻痹", poisoned: "中毒",
  diseased: "疾病", cursed: "诅咒", charmed: "魅惑", petrified: "石化" };
const esc = s => String(s ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
const effectActor = e => e.actor ?? e.parent?.actor ?? (e.parent?.documentName === "Actor" ? e.parent : null);
const effects = actor => Array.from(actor.appliedEffects ?? actor.effects ?? []).filter(e =>
  e.active && e.type !== "enchantment" && effectActor(e)?.uuid === actor.uuid);
const statuses = e => Array.from(e.statuses ?? []);
const categoryStatus = { disease: "diseased", curse: "cursed" };
const numeric = value => (typeof value === "number" || typeof value === "string" && value.trim() !== "")
  && Number.isFinite(Number(value)) ? Number(value) : null;
function reduction(change, actor, kind) {
  if (kind === "ability" ? !/^system\.abilities\.[^.]+\.value$/.test(change.key)
    : change.key !== "system.attributes.hp.tempmax") return false;
  const value = numeric(change.value);
  if (value === null) return false;
  const type = change.type ?? ({ 1: "multiply", 2: "add", 3: "downgrade", 4: "upgrade", 5: "override" })[change.mode];
  if (type === "add") return value < 0;
  if (type === "subtract") return value > 0;
  const source = change.key.split(".").reduce((data, key) => data?.[key], actor._source);
  const base = numeric(source);
  if (base === null) return false;
  if (type === "multiply") return value >= 0 && base * value < base;
  if (["downgrade", "override"].includes(type)) return value < base;
  return false;
}
function matches(effect, kind, actor) {
  if (["ability", "hpmax"].includes(kind)) return (effect.system?.changes ?? []).some(c => reduction(c, actor, kind));
  return statuses(effect).includes(categoryStatus[kind] ?? kind);
}
const describe = e => {
  const labels = statuses(e).map(s => names[s] ?? game.i18n.localize(CONFIG.statusEffects[s]?.name ?? s));
  const changes = (e.system?.changes ?? []).map(c => `${c.key}: ${c.value}`).join("；");
  return `${labels.join("、")}${labels.length && changes ? "；" : ""}${changes}`;
};
function rootEffect(effect, actor) {
  const seen = new Set();
  while (!seen.has(effect.uuid)) {
    seen.add(effect.uuid);
    const parentUuid = effect.flags?.dnd5e?.dependentOn;
    if (!parentUuid) break;
    const parent = actor.effects?.get?.(parentUuid)
      ?? fromUuidSync(parentUuid, { relative: effect, strict: false });
    // 不沿着专注关系删除另一名施法者的效果。
    if (parent?.documentName !== "ActiveEffect" || !parent.active
      || ["enchantment", "concentration"].includes(parent.type) || statuses(parent).includes("concentrating")
      || effectActor(parent)?.uuid !== actor.uuid) break;
    effect = parent;
  }
  return effect;
}
async function selectEffect(actor, list, category) {
  const rows = list.map(e => ({ id: e.uuid, uuid: e.uuid,
    name: `${e.name}${statuses(e).length ? `（${statuses(e).map(s => names[s] ?? s).join("、")}）` : ""}`,
    img: e.img, system: { description: { value: `${e.description ?? ""}<p>${esc(describe(e))}</p>` } } }));
  const selected = await dialogs.selectDocumentDialog(`${title}：${category}`, esc(actor.name), rows,
    { displayTooltips: true, width: 520 });
  return list.find(e => e.uuid === selected?.id);
}

const existing = workflow[key];
if (existing?.pending) return await existing.pending;
if (existing) return;
const state = workflow[key] = {};
state.pending = (async () => {
  await (async () => {
    const actors = new Map(Array.from(workflow.targets ?? [], t => [t.actor?.uuid, t.actor]).filter(([id]) => id));
    if (actors.size !== 1) {
      ui.notifications.warn(`${title}：请选择一个生物。`);
      state.cancelled = true;
      return false;
    }
    const actor = actors.values().next().value;
    const list = effects(actor);
    const kinds = greater ? ["charmed", "petrified"] : ["blinded", "deafened", "paralyzed", "poisoned"];
    const buttons = kinds.filter(s => list.some(e => statuses(e).includes(s)))
      .map(s => [names[s], s, { image: CONFIG.statusEffects[s]?.img }]);
    if (greater && Number(actor.system.attributes.exhaustion) > 0) buttons.unshift(["力竭降低一级", "exhaustion"]);
    const attuned = Array.from(actor.items ?? []).filter(i => i.system.attuned);
    if (greater) {
      for (const [label, category] of [["诅咒效应", "curse"], ["属性值减损", "ability"], ["生命值上限减损", "hpmax"]]) {
        if (list.some(e => matches(e, category, actor))) buttons.push([label, category]);
      }
      if (attuned.length) buttons.push(["解除被诅咒物品的同调", "attunement"]);
    } else if (list.some(e => matches(e, "disease", actor))) buttons.push(["一项疾病", "disease"]);
    if (!buttons.length) {
      ui.notifications.info(`${title}：目标身上没有可供选择的状态或效应。`);
      state.cancelled = true;
      return false;
    }
    const kind = await dialogs.buttonDialog(title, esc(actor.name), buttons, { width: 440 });
    if (!buttons.some(b => b[1] === kind)) { state.cancelled = true; return false; }
    state.actor = actor.uuid;
    state.kind = kind;
    if (kind === "exhaustion") return;
    if (kind === "attunement") {
      const item = await dialogs.selectDocumentDialog(`${title}：选择被诅咒的同调物品`, esc(actor.name), attuned,
        { displayTooltips: true, width: 520 });
      if (!item || !attuned.some(i => i.uuid === item.uuid)) { state.cancelled = true; return false; }
      state.item = item.uuid;
      return;
    }
    const condition = kinds.includes(kind);
    const candidates = list.filter(e => matches(e, kind, actor));
    const label = names[kind] ?? ({ disease: "选择疾病效应", curse: "选择诅咒效应", ability: "选择属性值减损效应", hpmax: "选择生命上限减损效应" })[kind];
    const effect = await selectEffect(actor, candidates, label);
    if (!effect) { state.cancelled = true; return false; }
    const root = rootEffect(effect, actor);
    state.effect = root.uuid;
    state.statusEffect = effect.uuid;
    state.mode = "effect";
    if (condition && (root.uuid !== effect.uuid || statuses(root).some(s => s !== kind))) {
      const mode = await dialogs.buttonDialog(title, `${esc(root.name)}<p>${esc(describe(root))}</p>`, [
        [`仅解除${names[kind]}状态`, "status"], ["终止整个效应", "effect"]
      ], { width: 520 });
      if (!["status", "effect"].includes(mode)) { state.cancelled = true; return false; }
      state.mode = mode;
    }
  })();
  if (state.cancelled) return false;
  if (workflow.aborted) return;
  const actor = await fromUuid(state.actor);
  if (!actor || !Array.from(workflow.targets ?? []).some(t => t.actor?.uuid === state.actor)) {
    ui.notifications.warn(`${title}：施法目标已改变，未执行解除。`);
    return;
  }
  const gm = async (handler, data) => {
    const result = await MidiQOL.socket().executeAsGM(handler, data);
    if (result === false || result === "gmBlocked") throw new Error(`${title}：GM 未能执行 ${handler}`);
    return result;
  };
  const endEffect = async effect => {
    const options = { "expiry-reason": `dnd5e_classpack:${greater ? "greater" : "lesser"}-restoration` };
    if (effect.transfer) return await gm("updateEffects", {
      actorUuid: effect.parent.uuid, updates: [{ _id: effect.id, disabled: true }]
    });
    if (effect.isOwner) return await effect.delete(options);
    // 永久诅咒必须真正删除；仅标记 duration.expired 可能被无限时长重新激活。
    const result = await DAE.deleteActiveEffect(actor.uuid, effect.origin, [], [effect.id], false, options);
    if (result === false) throw new Error(`${title}：所选效应未能删除`);
  };
  if (state.kind === "exhaustion") {
    if (Number(actor.system.attributes.exhaustion) > 0) await gm("toggleStatusEffect", {
      actorUuid: actor.uuid, statusId: "exhaustion", options: { levels: -1 }
    });
    return;
  }
  if (state.kind === "attunement") {
    const item = await fromUuid(state.item);
    if (item?.actor?.uuid === actor.uuid && item.system.attuned) await gm("updateItems", {
      actorUuid: actor.uuid, updates: [{ _id: item.id, "system.attuned": false }]
    });
    return;
  }
  const effect = await fromUuid(state.effect);
  const current = effects(actor);
  if (!effect || !current.some(e => e.uuid === effect.uuid)) {
    ui.notifications.info(`${title}：所选效应已不再生效。`);
    return;
  }
  const condition = (greater ? ["charmed", "petrified"] : ["blinded", "deafened", "paralyzed", "poisoned"]).includes(state.kind);
  const selected = await fromUuid(state.statusEffect);
  if (!selected || !current.some(e => e.uuid === selected.uuid) || !matches(selected, state.kind, actor)) return;
  const statusEffect = condition ? await fromUuid(state.statusEffect) : null;
  if (condition && (!statusEffect || !current.some(e => e.uuid === statusEffect.uuid)
    || !statuses(statusEffect).includes(state.kind))) return;
  if (state.mode === "status") {
    // 只修改使用者选中的状态，不删除该 AE 的其他状态或数值变更。
    const remaining = statuses(statusEffect).filter(s => s !== state.kind);
    const riders = Array.from(effect.system?.rider?.statuses ?? []);
    if (effect.uuid !== statusEffect.uuid && riders.includes(state.kind)) await gm("updateEffects", {
      actorUuid: effect.parent.uuid,
      updates: [{ _id: effect.id, "system.rider.statuses": riders.filter(s => s !== state.kind) }]
    });
    if (remaining.length || statusEffect.system?.changes?.length
      || Array.from(statusEffect.system?.rider?.statuses ?? []).length) await gm("updateEffects", {
      actorUuid: statusEffect.parent.uuid, updates: [{ _id: statusEffect.id, statuses: remaining }]
    });
    else await endEffect(statusEffect);
    return;
  }
  await endEffect(effect);
})();
try { return await state.pending; }
catch (error) {
  console.error(`${title}：解除失败`, error);
  ui.notifications.error(`${title}：未完成解除，请检查控制台。`);
  return false;
}
finally { delete state.pending; state.done = true; }
